from pathlib import Path
import json,re

target='DEV-PRED-ASTRA-FIRSTFAIL-FIX-TEST-20261005'
state=Path.home()/'.local/state/prediction-project-executor'/f'{target}.json'
bridge=Path.home()/'.local/share/prediction-chat-bridge'
parts=[]

if state.is_file():
    try:
        obj=json.loads(state.read_text(encoding='utf-8'))
        parts.append('EXECUTOR_STATUS='+str(obj.get('status')))
        parts.append('SOURCE_COMMIT='+str(obj.get('source_commit')))
        parts.append('HEAD_AFTER='+str(obj.get('head_after')))
        parts.append('OP_COUNT='+str(obj.get('operation_count')))
    except Exception as exc:
        parts.append('STATE_PARSE_ERROR='+exc.__class__.__name__)
else:
    parts.append('EXECUTOR_STATUS=MISSING')

found=[]
for dname in ('outbox','inflight','sent'):
    d=bridge/dname
    if not d.exists():
        continue
    for p in d.glob('*.json'):
        try:
            o=json.loads(p.read_text(encoding='utf-8',errors='replace'))
        except Exception:
            continue
        if str(o.get('task_id') or '')!=target:
            continue
        msg=str(o.get('message') or '')
        status=re.search(r'DEV_TASK_STATUS=(PASS|FAIL)',msg)
        rcs=re.findall(r'COMMAND_(\d+)_RC=(-?\d+)',msg)
        tests=[]
        for name in (
            'test_candidate_dispatch_legacy_needs_build_cannot_bypass_astra',
            'test_stale_approved_overlay_cannot_retrigger_build_after_source_change',
        ):
            if name in msg:
                tests.append(name)
        found.append({
            'queue':dname,
            'event_id':o.get('event_id'),
            'dev_status':status.group(1) if status else None,
            'rcs':rcs,
            'tests_seen':tests,
            'tail':re.sub(r'\s+',' ',msg[-1800:])[:1800],
        })

if found:
    f=found[-1]
    parts.append('QUEUE='+str(f['queue']))
    parts.append('EVENT='+str(f['event_id']))
    parts.append('DEV_STATUS='+str(f['dev_status']))
    parts.append('RCS='+','.join(a+':'+b for a,b in f['rcs']))
    parts.append('TESTS_SEEN='+str(len(f['tests_seen'])))
    if f['tests_seen']:
        parts.append('TEST_NAMES='+','.join(f['tests_seen']))
    if f['tail']:
        parts.append('TAIL='+f['tail'])
else:
    parts.append('WAKE_EVENT=NOT_FOUND')

print('FIX_PROOF='+' || '.join(parts),flush=True)
raise SystemExit(42)
